pub(crate) fn check_handed_root(view: &ParsedView<'_, '_, '_, '_, '_, '_>, place: &Expr) -> Option<String> {
    match place {
        Expr::Variable(name, _) => { let name = *name; Some(view.text(name)) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); check_handed_root(view, base) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); check_handed_root(view, base) },
        _ => None,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_handed_carries(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, view: &ParsedView<'_, '_, '_, '_, '_, '_>, key: &str, expr: &Expr, held: &collections::BTreeMap<String, String>) -> Option<String> {
    match expr {
        Expr::Variable(name, id) => { let id = *id; let name = *name; return check_handed_holds(view, key, name, id.get(), held); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); return check_handed_carries(world, view, key, base, held); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); return check_handed_carries(world, view, key, base, held); },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); return check_handed_carries(world, view, key, base, held); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); return check_handed_carries(world, view, key, inner, held); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); return check_handed_carries(world, view, key, expr, held); },
        Expr::Block(block, _) => { return check_handed_carries_block(world, view, key, block, held); },
        Expr::If { then_branch, else_branch, .. } => {
            let first = check_handed_carries_block(world, view, key, then_branch, held);
            if first.is_some() { return std::convert::identity(first); }
            if else_branch.is_some() { return check_handed_carries_block(world, view, key, match else_branch { Some(__nikaia_value) => __nikaia_value, None => return None }, held); }
            return None;
        },
        Expr::Match { arms, .. } => {
            for arm in arms.iter() {
                let origin = check_handed_carries(world, view, key, &arm.body, held);
                if origin.is_some() { return std::convert::identity(origin); }
            }
            return None;
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = nikaia_std::index::or(check_handed_callee(view, func), || "".into());
            if world.library.functions.contains_key(&callee) { return None; }
            let contract = world.own.functions.get(&callee);
            if contract.is_some() && nikaia_std::index::or(contract.as_ref().map(|__nikaia_it| __nikaia_it.described), || false) { return None; }
            for arg in args.iter() {
                let origin = check_handed_carries(world, view, key, arg, held);
                if origin.is_some() { return std::convert::identity(origin); }
            }
            return None;
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let word = view.text(method);
            let mut own = false;
            for (name, contract) in world.own.functions.iter() { if !contract.described && name.ends_with(&*format!("::{}", word)) { own = true; } }
            if !own { return None; }
            let origin = check_handed_carries(world, view, key, receiver, held);
            if origin.is_some() { return std::convert::identity(origin); }
            for arg in args.iter() {
                let found = check_handed_carries(world, view, key, arg, held);
                if found.is_some() { return std::convert::identity(found); }
            }
            return None;
        },
        _ => { },
    }
    for child in check_visit_children(expr) {
        let origin = check_handed_carries(world, view, key, child, held);
        if origin.is_some() { return std::convert::identity(origin); }
    }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_handed_carries_block(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, view: &ParsedView<'_, '_, '_, '_, '_, '_>, key: &str, block: &Block, held: &collections::BTreeMap<String, String>) -> Option<String> {
    let count = block.stmts.len() as i64;
    if count == 0 { return None; }
    match &unsafe { nikaia_std::proven::read(&block.stmts, (nikaia_std::proven::sub::<i64>(count, 1)) as usize) }.node {
        Stmt::Expr(value) => check_handed_carries(world, view, key, value, held),
        _ => None,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_handed_written(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, key: &str, expr: &Expr, held: &collections::BTreeMap<String, String>) -> Option<String> {
    match expr {
        Expr::Variable(name, id) => {
            let id = *id; let name = *name;
            if check_handed_holds(&world.here, key, name, id.get(), held).is_some() { return Some(world.here.text(name)); }
            return None;
        },
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            let inner = match check_handed_written(world, key, base, held) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(match base {
                Expr::Variable(_, _) => format!("{}.{}", inner, world.here.text(name)),
                Expr::Field { .. } => format!("{}.{}", inner, world.here.text(name)),
                _ => inner,
            });
        },
        _ => { },
    }
    for child in check_visit_children(expr) {
        let found = check_handed_written(world, key, child, held);
        if found.is_some() { return std::convert::identity(found); }
    }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_handed_pattern_names(view: &ParsedView<'_, '_, '_, '_, '_, '_>, pattern: &MatchPattern) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    match pattern {
        MatchPattern::Path(segments) => { if segments.len() == 1 { out.push(view.text(*unsafe { nikaia_std::proven::read(&segments, (0) as usize) })); } },
        MatchPattern::Tuple { parts, .. } => { for part in parts.iter() { out.extend(check_handed_pattern_names(view, part)); } },
        MatchPattern::List(parts) => { for part in parts.iter() { out.extend(check_handed_pattern_names(view, part)); } },
        MatchPattern::RestNamed(name) => { let name = *name; out.push(view.text(name)); },
        MatchPattern::Named { fields, .. } => { for field in fields.iter() { out.extend(check_handed_pattern_names(view, &field.pat)); } },
        MatchPattern::Or(alternatives) => { if !alternatives.is_empty() { out.extend(check_handed_pattern_names(view, unsafe { nikaia_std::proven::read(&alternatives, (0) as usize) })); } },
        _ => { },
    }
    out
}

